==> pakket/openstelling.yaml <==
index: 1
korteNaam: "FICTIEF Buurtbijdrage najaar 2026"
bron: "Artikel 7"
periode:
  begin: "2026-09-01T09:00:00+02:00"
  eind: "2026-12-31T17:00:00+01:00"
budget:
  plafond: 50000
  verdeelmethode: volgorde_van_binnenkomst

==> pakket/pakket.yaml <==
pakketCode: fictief-buurtbijdrage
fictief: true
korteNaam: "FICTIEF Buurtbijdrage"
langeNaam: "FICTIEF — Buurtbijdrage voor kleine activiteiten"
regeling: regeling/regeling.md

==> pakket/traceerbaarheid.yaml <==
# Elke eis (REQ) heeft een bron in de regeling. Elke vraag in het formulier hoort bij een eis.
eisen:
  REQ-FB-001: { omschrijving: "Aanvrager is een buurtorganisatie met KvK-nummer, naam en adres.", bron: "Artikel 3" }
  REQ-FB-002: { omschrijving: "De activiteit heeft een naam, omschrijving, categorie, datum en verwacht aantal deelnemers.", bron: "Artikel 4" }
  REQ-FB-003: { omschrijving: "Gevraagd bedrag; boven EUR 5.000 volgt een signalering.", bron: "Artikel 5" }
  REQ-FB-004: { omschrijving: "Andere financiering melden, met toelichting.", bron: "Artikel 4" }
  REQ-FB-005: { omschrijving: "Optioneel een activiteitenplan meesturen.", bron: "Artikel 5" }
  REQ-FB-006: { omschrijving: "Aanvrager verklaart de gegevens naar waarheid te hebben ingevuld.", bron: "Artikel 4" }

==> pakket/versie.yaml <==
versie: 1.0.0
geldigVanaf: "2026-09-01"
wijzigingen:
  - versie: 1.0.0
    datum: "2026-08-01"
    omschrijving: "Eerste versie."

==> pakket/aanvraag/mapping.yaml <==
# Welke antwoorden het platform overneemt in de zaak. Antwoorden die hier niet staan,
# blijven alleen in de aanvraaggegevens (en zijn wel zichtbaar voor de behandelaar).
zaak:
  aangevraagdBedrag: { pad: gevraagdBedrag, req: [REQ-FB-003] }
aanvrager:
  kvkNummer: { pad: aanvrager.kvkNummer, req: [REQ-FB-001] }
  naam: { pad: aanvrager.naam, req: [REQ-FB-001] }

==> pakket/aanvraag/schema.json <==
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Aanvraag FICTIEF Buurtbijdrage",
  "type": "object",
  "required": ["aanvrager", "activiteit", "gevraagdBedrag", "andereFinanciering", "verklaring"],
  "properties": {
    "aanvrager": {
      "type": "object",
      "required": ["kvkNummer", "naam", "adres"],
      "properties": {
        "kvkNummer": { "type": "string", "pattern": "^[0-9]{8}$" },
        "naam": { "type": "string", "minLength": 1, "maxLength": 200 },
        "adres": { "type": "string", "minLength": 5, "maxLength": 300 }
      }
    },
    "activiteit": {
      "type": "object",
      "required": ["titel", "omschrijving", "categorie", "datum", "aantalDeelnemers"],
      "properties": {
        "titel": { "type": "string", "minLength": 3, "maxLength": 120 },
        "omschrijving": { "type": "string", "minLength": 20, "maxLength": 1000 },
        "categorie": { "enum": ["sport", "cultuur", "groen"] },
        "datum": { "type": "string", "format": "date" },
        "aantalDeelnemers": { "type": "integer", "minimum": 1, "maximum": 10000 }
      }
    },
    "gevraagdBedrag": { "type": "number", "exclusiveMinimum": 0 },
    "andereFinanciering": { "type": "boolean" },
    "andereFinancieringToelichting": { "type": "string", "minLength": 5, "maxLength": 500 },
    "activiteitenplan": { "type": "string" },
    "verklaring": { "type": "boolean", "const": true }
  }
}

==> pakket/aanvraag/teksten.nl.yaml <==
titel: "FICTIEF — Buurtbijdrage aanvragen"
intro: "Vraag een kleine bijdrage aan voor een activiteit in uw buurt."
stappen:
  aanvrager: { titel: "Uw organisatie" }
  activiteit: { titel: "De activiteit" }
  bijdrage: { titel: "Uw bijdrage" }
  indienen: { titel: "Controleren en indienen", intro: "Controleer uw gegevens. Klopt alles? Dan kunt u de aanvraag indienen." }
velden:
  aanvrager.kvkNummer: { label: "KvK-nummer", hulp: "8 cijfers." }
  aanvrager.naam: { label: "Naam van uw organisatie" }
  aanvrager.adres: { label: "Adres van uw organisatie" }
  activiteit.titel: { label: "Naam van de activiteit" }
  activiteit.omschrijving: { label: "Wat gaat u doen?", hulp: "Beschrijf in een paar zinnen wat er gebeurt en voor wie." }
  activiteit.categorie:
    label: "Wat voor activiteit is het?"
    opties: { sport: "Sport en bewegen", cultuur: "Cultuur", groen: "Groen in de buurt" }
  activiteit.datum: { label: "Op welke datum is de activiteit?" }
  activiteit.aantalDeelnemers: { label: "Hoeveel mensen doen ongeveer mee?" }
  gevraagdBedrag:
    label: "Welk bedrag vraagt u aan?"
    hulp: "U kunt maximaal 5.000 euro krijgen."
    signalering: "U vraagt meer dan 5.000 euro. U kunt toch indienen, maar u krijgt maximaal 5.000 euro."
  andereFinanciering:
    label: "Krijgt u ook geld van anderen voor deze activiteit?"
    opties: { "true": "Ja", "false": "Nee" }
  andereFinancieringToelichting: { label: "Van wie krijgt u geld, en hoeveel?" }
  activiteitenplan: { label: "Activiteitenplan (niet verplicht)", hulp: "PDF of Word, maximaal 10 MB." }
  verklaring:
    label: "Verklaring"
    opties: { "true": "Ik verklaar dat ik alles naar waarheid heb ingevuld." }
bevestiging: "Wij hebben uw aanvraag ontvangen."

==> pakket/aanvraag/wizard.yaml <==
# De stappen en vragen van het aanvraagformulier, in volgorde.
stappen:
  - id: aanvrager
    velden:
      - { pad: aanvrager.kvkNummer, type: tekst, req: [REQ-FB-001] }
      - { pad: aanvrager.naam, type: tekst, req: [REQ-FB-001] }
      - { pad: aanvrager.adres, type: tekst, req: [REQ-FB-001] }
  - id: activiteit
    velden:
      - { pad: activiteit.titel, type: tekst, req: [REQ-FB-002] }
      - { pad: activiteit.omschrijving, type: tekst, meerregelig: true, req: [REQ-FB-002] }
      - { pad: activiteit.categorie, type: keuze, req: [REQ-FB-002] }
      - { pad: activiteit.datum, type: datum, req: [REQ-FB-002] }
      - { pad: activiteit.aantalDeelnemers, type: getal, req: [REQ-FB-002] }
  - id: bijdrage
    velden:
      # Een maximum blokkeert niet: de aanvrager ziet een signalering en kan toch indienen.
      - { pad: gevraagdBedrag, type: bedrag, req: [REQ-FB-003], signalering: { boven: 5000 } }
      - { pad: andereFinanciering, type: keuze, req: [REQ-FB-004] }
      - pad: andereFinancieringToelichting
        type: tekst
        meerregelig: true
        req: [REQ-FB-004]
        zichtbaarAls: { veld: andereFinanciering, is: true }
      - { pad: activiteitenplan, type: upload, req: [REQ-FB-005] }
  - id: indienen
    velden:
      - { pad: verklaring, type: keuze, req: [REQ-FB-006] }

